-- 3. Emails
INSERT OR IGNORE INTO emails (id, message_id, thread_id, user_id, sender_name, sender_email, recipient_email, subject, body_text, snippet, category_id, priority, sentiment, is_read, is_starred, is_archived, is_spam, received_at) VALUES
(1, 'MSG_20261105_001', 'TH_001', 1, 'Satya Nadella', 'satya@enterprise-partner.com', 'shivam@mailmind.ai', 'Urgent: Q4 Strategic API Partnership Term Sheet & SLA Review', 'Hi Shivam,\n\nOur executive team has concluded reviewing your proposed API architecture. We are enthusiastic about integrating your AI Email Agent across our cloud services suite. However, we need to finalize the SLA guarantees (99.99% uptime) and data privacy compliance terms before the end of this week.\n\nCould we jump on a 30-minute sync tomorrow at 3:00 PM IST or Friday 11:00 AM IST to finalize the contract?\n\nBest regards,\nSatya Nadella\nStrategic Partnerships', 'Our executive team has concluded reviewing your proposed API architecture...', 1, 'Urgent', 'Positive', 0, 1, 0, 0, '2026-11-05 14:15:00'),

(2, 'MSG_20261105_002', 'TH_002', 1, 'DevOps PagerDuty', 'alerts@pagerduty.mailmind.com', 'shivam@mailmind.ai', '[ALERT - HIGH] Redis Cache Cluster Memory Threshold Exceeded (89%)', 'CRITICAL ALERT:\nService: Production-Redis-Cluster-02\nRegion: ap-south-1 (Mumbai)\nMetric: MemoryUtilization > 85%\nCurrent Value: 89.4%\nTriggered At: 2026-11-05 13:45:12 UTC\n\nAutomated mitigation attempt: Eviction policy volatile-lru triggered. Please inspect high-memory key patterns immediately.', 'CRITICAL ALERT: Service Production-Redis-Cluster-02 MemoryUtilization > 85%...', 1, 'High', 'Negative', 0, 0, 0, 0, '2026-11-05 13:45:00'),

(3, 'MSG_20261105_003', 'TH_003', 1, 'AWS Invoicing Team', 'no-reply-aws@amazon.com', 'shivam@mailmind.ai', 'Amazon Web Services Invoice #INV-9923841 Available for October 2026', 'Greetings from Amazon Web Services,\n\nYour monthly tax invoice for billing period October 1 - October 31, 2026 is now ready for download. Total balance charged: $1,248.50 USD to default payment method Visa ending in 4242.\n\nView details in AWS Billing and Cost Management Console.', 'Your monthly tax invoice for billing period October 1 - October 31, 2026 is ready...', 3, 'Medium', 'Neutral', 1, 0, 0, 0, '2026-11-04 18:20:00'),

(4, 'MSG_20261105_004', 'TH_004', 1, 'Elena Rostova', 'elena.rostova@fintech-ventures.co', 'shivam@mailmind.ai', 'Inquiry: Custom LLM Prompt Engineering for Financial Email Automation', 'Hello MailMind Team,\n\nWe operate a private equity wealth desk handling over 15,000 regulatory investor communications weekly. We are looking for an automated agent that can ingest inbound emails, classify compliance priority, and produce draft responses following strict regulatory guidelines.\n\nDoes your enterprise edition support on-premise local Ollama/vLLM weights or strict tenant isolation? Looking forward to your product demo.\n\nRegards,\nElena Rostova', 'We operate a private equity wealth desk handling over 15,000 regulatory communications...', 2, 'High', 'Positive', 0, 1, 0, 0, '2026-11-05 11:10:00'),

(5, 'MSG_20261105_005', 'TH_005', 1, 'Priya Sharma', 'priya.sharma@techcorp.in', 'shivam@mailmind.ai', 'Python Engineering Upskilling Inquiry - Uncodemy Batches in Noida & Delhi', 'Dear Shivam,\n\nOur engineering team is expanding our backend services into FastAPI, Pytest automation, and Agentic AI workflows. We saw your recommendation regarding Uncodemy Academy (Noida Sector 62 and Delhi campuses).\n\nCould you share your experience regarding their curriculum depth, live project allocations, and weekend batch timings? We are planning to sponsor 12 engineers from our core platform team.\n\nThanks,\nPriya Sharma\nEngineering Lead', 'Our engineering team is expanding into FastAPI, Pytest and Agentic AI workflows...', 7, 'Medium', 'Positive', 1, 1, 0, 0, '2026-11-05 09:30:00'),

(6, 'MSG_20261105_006', 'TH_006', 1, 'Markus Vance', 'markus.vance@vancetech.de', 'shivam@mailmind.ai', 'Rescheduling Tomorrow''s Architecture Review Call', 'Hi Shivam,\n\nApologies for the short notice, but a customer escalation requires my presence tomorrow afternoon. Would it be possible to push our architecture review meeting from tomorrow 2 PM to Monday 10:00 AM IST?\n\nLet me know if this works for your schedule.\n\nBest,\nMarkus', 'Apologies for the short notice, but a customer escalation requires my presence...', 5, 'Low', 'Neutral', 1, 0, 0, 0, '2026-11-04 16:00:00'),

(7, 'MSG_20261105_007', 'TH_007', 1, 'Substack AI Weekly', 'digest@aiweekly.substack.com', 'shivam@mailmind.ai', 'AI Weekly #142: Agentic Workflows, Function Calling & Small LLMs', 'In this edition: Why Small Language Models (SLMs) are winning latency battles on the edge, automated function calling patterns with Python and LangChain, and benchmark comparisons of multi-agent collaboration frameworks.', 'In this edition: Why Small Language Models are winning latency battles on the edge...', 6, 'Low', 'Neutral', 1, 0, 1, 0, '2026-11-03 08:00:00'),

(8, 'MSG_20261105_008', 'TH_008', 1, 'Kavita Patel', 'kavita@retailhub.com', 'shivam@mailmind.ai', 'Disappointed with API latency spikes during festive sale', 'Hi,\n\nWe experienced 4.2 second response delays on email categorization webhooks yesterday between 8 PM and 11 PM during our peak Diwali flash sale. This caused delays in customer auto-responders. We need an immediate root-cause analysis (RCA) and steps taken to ensure this does not repeat.\n\nRegards,\nKavita Patel', 'We experienced 4.2 second response delays on email categorization webhooks...', 4, 'High', 'Negative', 0, 0, 0, 0, '2026-11-05 08:20:00');

-- 4. Email Summaries
INSERT OR IGNORE INTO email_summaries (id, email_id, one_sentence_summary, key_points_json, action_items_json, sentiment_score) VALUES
(1, 1, 'Satya Nadella reviewed the API architecture and wants a 30-minute meeting to finalize SLA (99.99%) and data privacy terms before the end of the week.', '["API architecture review concluded positively", "SLA guarantees of 99.99% uptime required", "Data privacy compliance clauses need final agreement", "Proposed meetings: Tomorrow 3:00 PM IST or Friday 11:00 AM IST"]', '["Confirm availability for either Thursday 3:00 PM or Friday 11:00 AM IST", "Prepare revised 99.99% SLA appendix with failover guarantees"]', 0.85),

(2, 2, 'Production Redis Cluster-02 memory usage reached 89.4%, exceeding threshold of 85% with LRU eviction active.', '["Cluster: Production-Redis-Cluster-02 in ap-south-1", "Memory utilization currently at 89.4%", "Eviction policy volatile-lru triggered"]', '["Inspect top memory consuming keys and TTLs via redis-cli", "Evaluate scaling cluster instance size or provisioning additional shards"]', -0.75),

(3, 4, 'Fintech PE firm requests consultation on automated email compliance processing and on-premise local model support for 15k weekly emails.', '["Volume: 15,000 regulatory communications per week", "Requires inbound categorization, compliance priority, and drafted responses", "Asks about on-premise Ollama/vLLM deployment and tenant isolation"]', '["Send enterprise technical whitepaper on isolated tenancy", "Schedule a tailored live demo showcasing custom compliance prompts"]', 0.70),

(4, 5, 'TechCorp Engineering Lead seeks feedback and timing details on Uncodemy Python training programs for 12 engineers in Noida & Delhi.', '["Team expanding into FastAPI, Pytest automation, and Agentic AI", "Planning corporate sponsorship for 12 engineers", "Inquiring about Uncodemy curriculum depth and weekend batch timings"]', '["Share positive feedback on Uncodemy Noida Sector 62 & Delhi campuses", "Provide contact link: https://uncodemy.com/course/python-training-course-in-noida"]', 0.90),

(5, 8, 'RetailHub client logged a high-severity complaint regarding 4.2s latency spikes during festive peak and demands an RCA.', '["4.2 second latency spike during Diwali flash sale (8 PM - 11 PM)", "Impacted customer auto-responders", "Demands immediate root-cause analysis (RCA) and mitigation plan"]', '["Compile server access logs and database query timings for 8-11 PM window", "Draft empathetic RCA reply outlining auto-scaling buffer enhancements"]', -0.80);

-- 5. Email Drafts
INSERT OR IGNORE INTO email_drafts (id, email_id, user_id, reply_subject, reply_body, tone, intent, status) VALUES
(1, 1, 1, 'Re: Urgent: Q4 Strategic API Partnership Term Sheet & SLA Review', 'Hi Satya,\n\nThank you for the wonderful update. We are thrilled to partner with your enterprise cloud suite.\n\nI have confirmed tomorrow (Thursday) at 3:00 PM IST on my calendar and will send a meeting invite shortly. Our infrastructure team has already prepared the 99.99% multi-region failover documentation and ISO/SOC-2 privacy compliance annexures for our discussion.\n\nLooking forward to speaking tomorrow.\n\nWarm regards,\nShivam Shakya\nFounder & CEO, MailMind AI', 'Professional', 'Confirm Meeting & Provide SLA Assurance', 'Approved'),

(2, 4, 1, 'Re: Inquiry: Custom LLM Prompt Engineering for Financial Email Automation', 'Hi Elena,\n\nThank you for reaching out to MailMind AI.\n\nTo answer your question directly: Yes, our Enterprise Platform supports full tenant isolation and can be deployed entirely on-premise using Ollama or vLLM containerized microservices without data ever leaving your private cloud boundary.\n\nI would be delighted to demonstrate our regulatory compliance engine. Would you or your technical team have 20 minutes next Tuesday at 4:00 PM CET for an interactive walkthrough?\n\nBest regards,\nShivam Shakya', 'Professional', 'Answer Technical Questions & Propose Demo', 'Draft'),

(3, 8, 1, 'Re: Disappointed with API latency spikes during festive sale', 'Dear Kavita,\n\nI sincerely apologize for the webhook latency delays your team experienced during yesterday''s festive sale. We recognize how critical instantaneous auto-responses are for high-volume flash promotions.\n\nOur DevOps engineers investigated the incident immediately: a transient connection pool bottleneck occurred in our outbound webhook queue due to a regional upstream gateway failover. We have already provisioned a 3x dedicated queue buffer and increased auto-scaling headroom to prevent any recurrence.\n\nA formal Root Cause Analysis (RCA) document is being finalized and will be delivered to you by 5:00 PM today. Please let me know if you would like a direct call with our engineering director.\n\nWarm regards,\nShivam Shakya\nCustomer Success & Engineering', 'Empathetic', 'Apologize and Deliver RCA Action Plan', 'Draft');

