(2, 1, 'Auto-Archive Newsletters & Promotional Digests', 'Move incoming newsletters to archive after classification', 'category', 'equals', 'Newsletters & Updates', 'auto_archive', '{"archive": true}', 1, 48),
(3, 1, 'Alert Escalation for Production Server Warnings', 'Tag infrastructure alerts as Action Required and trigger desktop notification', 'subject', 'contains', '[ALERT', 'assign_category', '{"category_id": 1, "priority": "Urgent"}', 1, 23),
